#include "rx.h"
using namespace std;const int N=304;vector<int>a[N];struct R{array<int,5> n;string g;double cost,net,gross,heat;int cool;};
static const int moAv=(int)PI("moAv"),moHs=(int)PI("moHs"),moEx=(int)PI("moEx"),moPlat=(int)PI("moPlat"),moTicks=(int)PI("moTicks");
bool run(R&r,int order,double&net,int&cool){array<double,N>h{};string g=r.g;int K=(int)count(g.begin(),g.end(),'K'),P=(int)count(g.begin(),g.end(),'P'),F=(int)count(g.begin(),g.end(),'1');double hc=P*M.hullPer,rate=M.rate0*(M.bEx+moEx)*2*(1+M.capBoost*K),vr=M.vr0*(1+M.ventBoost*(M.bAv+moAv)*K),vc=M.vc0*(1+M.sinkBoost*(M.bHs+moHs)*P),sell=M.sales(K),hull=0,income=0;array<double,N>cap{};for(int i=0;i<N;i++)cap[i]=g[i]=='C'?M.ccap:g[i]=='V'?vc:g[i]=='K'?M.kcap:0;int branches=0;for(int i=0;i<N;i++)if(g[i]=='O')for(int j:a[i])branches+=cap[j]>0;
 for(int t=0;t<moTicks;t++){double power=0,b=hull>0?M.boost(max(1.,hull)):1.;if(t<M.expStart)for(int i=0;i<N;i++)if(g[i]=='1'){int pulse=1,refs=0,ns=0;for(int j:a[i]){pulse+=g[j]=='1';refs+=g[j]=='R';ns+=cap[j]>0;}power+=M.fuelPow*pulse*(1+M.refl*refs)*b;double q=M.fuelHeat*pulse*pulse;if(ns)for(int j:a[i]){if(cap[j]>0)h[j]+=q/ns;}if(!ns)hull+=q;}income+=min(power,sell);double per=branches?min(hull/branches,rate):0;
 for(int z=0;z<N;z++){int i=order?N-1-z:z;if(g[i]=='I')for(int j:a[i]){double q=min(rate,h[j]);h[j]-=q;hull+=q;}if(g[i]=='O')for(int j:a[i])if(cap[j]>0){double q=min(per,hull);h[j]+=q;hull-=q;}}
 for(int i=0;i<N;i++)if(g[i]=='V')h[i]=max(0.,h[i]-vr);if(hull>=hc)return false;for(int i=0;i<N;i++)if(cap[i]>0&&h[i]>=cap[i])return false;hull=max(0.,hull-hc*M.drain);if(t>=M.expStart-1){double total=hull;for(double x:h)total+=x;if(total<1){cool=t-(M.expStart-1);net=(income-F*PR.f1*1e6)/(t+1);return true;}}}return false;}
int main(){for(int i=0;i<N;i++){if(i%19)a[i].push_back(i-1);if(i%19<18)a[i].push_back(i+1);if(i>=19)a[i].push_back(i-19);if(i<285)a[i].push_back(i+19);}mt19937 rng((unsigned)PI("moSeed"));long long draws=PI("moDraws");int slots=clamp((int)PI("moSlots"),1,30),maxF=(int)PI("moMaxF");if(PI("moSlots")>30)cerr<<"модулей не больше 30 (сетка 6x5), взято 30\n";set<array<int,5>>seen;long tried=0,screen=0,sim=0,pass=0;double best=-1e99;ofstream csv("results.csv");csv<<"A,B,C,D,E,cost_Qa,net_B_per_tick,cooldown_ticks,status\n";
 for(long long z=0;z<draws;z++){if(z&&z%100000==0)cerr<<"попыток "<<z<<" уникальных "<<tried<<" прошли "<<pass<<"\n";array<int,5>n{};int left=slots;for(int j=0;j<5;j++){n[j]=rng()%(left+1);left-=n[j];}shuffle(n.begin(),n.end(),rng);if(!seen.insert(n).second)continue;tried++;int F=n[2]+n[3];if(!F||F>maxF)continue;string g(N,'K');int slot=0;for(int typ=0;typ<5;typ++)for(int m=0;m<n[typ];m++){int x=(slot%6)*3,y=(slot/6)*3,i=(y+1)*19+x+1;slot++;if(typ<4){g[i]=typ<2?'O':'1';char c=typ==0?'V':typ==1?'C':typ==2?'R':'I';for(int j:a[i])g[j]=c;}else{g[i]='I';g[i-1]=g[i+1]='O';for(int dx:{-1,1})for(int dy:{-1,1})g[i+dx+dy*19]='V';}}
 for(int i=N-1,p=0;i>=0&&p<moPlat;i--)if(g[i]=='K'){g[i]='P';p++;}array<int,128>cnt{};for(char c:g)cnt[c]++;int K=cnt['K'],V=cnt['V'],C=cnt['C'],Pl=cnt['P'];double cost=PR.fuel(cnt)+PR.upgrades(moAv,moHs,moEx,0,0)+PR.parts(cnt);if(cost>PR.budget)continue;screen++;double heat=F*M.fuelHeat,cooling=V*M.vr0*(1+M.ventBoost*(M.bAv+moAv)*K);if((heat-cooling)*M.expStart>C*M.ccap+Pl*M.hullPer+V*M.vc0*(1+M.sinkBoost*(M.bHs+moHs)*Pl))continue;sim++;R r{n,g,cost,0,0,heat,0};double n0,n1;int c0,c1;bool ok=run(r,0,n0,c0)&&run(r,1,n1,c1);for(int v:n)csv<<v<<',';csv<<cost<<','<<(ok?min(n0,n1):0)<<','<<(ok?max(c0,c1):0)<<','<<(ok?"PASS":"FAIL")<<'\n';if(!ok)continue;pass++;if(min(n0,n1)>best){best=min(n0,n1);ofstream f("best.txt");f<<setprecision(12)<<"net_B "<<best<<" cost_Qa "<<cost<<" cooldown "<<max(c0,c1)<<"\n";for(int v:n)f<<v<<' ';f<<'\n';for(int y=0;y<16;y++)f<<g.substr(y*19,19)<<'\n';cerr<<"новый лучший net "<<best<<" цена "<<cost<<"\n";}}
 ofstream st("stats.txt");st<<"draws "<<draws<<" unique "<<tried<<" budget_pass "<<screen<<" simulated "<<sim<<" passed "<<pass<<" best_net_B "<<best<<'\n';cout<<"done "<<tried<<' '<<sim<<' '<<pass<<' '<<best<<'\n';return 0;}
